from depth import *

Lecture('system-boundary',[
Q('purpose','Назначение и результат ИС','Начнём с работы предприятия. Название программы ещё не определяет систему: нужно установить, какой результат должен получить конкретный участник и по каким данным мы его подтвердим.',[
 O(1),
 S('Данные становятся информацией в контексте','Запись «24» сама по себе не сообщает, что произошло. «24 упаковки товара A приняты на склад 1 по документу П-17» связывает величину, единицу, объект, место и событие. Изменение контекста меняет смысл той же последовательности символов.','Сравните 24 упаковки и 24 штуки при 12 штуках в упаковке: второй остаток в 12 раз меньше первого. Формат хранения может оставаться числовым, поэтому правильный тип поля ещё не гарантирует правильный смысл. Для эксплуатации проверяем также единицу и справочник.'),
 E('Функция — действие с проверяемым завершением','Учебная функция «принять поставку»: вход — накладная П-17 и фактически принятый товар; действие — проверка и проведение; выход — проведённый документ и новый остаток. Открытая форма является только промежуточным состоянием.','При исходном остатке 10 и приёмке 24 упаковок ожидаем 34 упаковки, одну проведённую П-17 и запись исполнителя. Если форма сообщила об успехе, а остаток остался 10, функция ещё не подтверждена.',process([('Вход','П-17: 24 упаковки'),('Проверка','Товар, количество, полномочие'),('Результат','П-17 проведена; остаток 34')],'Начальный остаток — 10 упаковок; повторный ввод того же документа не должен удваивать приёмку.')),
 O(2)],Check('Какая запись достаточнее для проверки приёмки?', ['Приложение открыто','В журнале есть П-17, принято 24 упаковки, остаток изменён с 10 на 34','CPU загружен на 20%'],1,'Наблюдение связано с требуемой функцией, исходными данными и результатом. Открытие формы и загрузка CPU этого не доказывают.'),'Работоспособность ИС подтверждают результатом функции, а не наличием программы.'),
Q('technical','Техническое обеспечение','Теперь отделим физические средства от правил работы. Один отказ питания может остановить несколько программ, а неисправность периферии — только одну операцию.',[
 S('Вычисление, передача и хранение','Клиентское устройство принимает ввод; процессор исполняет команды; оперативная память держит текущее состояние; накопитель сохраняет данные; сеть связывает узлы. Эти роли могут совмещаться в одном компьютере, но различаются при поиске неисправности.','Выключение питания очищает обычную оперативную память, поэтому несохранённая форма и проведённый документ имеют разную судьбу. Проверяя потерю данных, установите, достигла ли операция устойчивого хранения. Сам факт наличия диска не говорит, когда приложение завершило запись.'),
 S('Общие физические зависимости','Питание, охлаждение, кабельные трассы и место размещения обеспечивают работу оборудования. Два сервера, подключённые к одному неисправному источнику питания, не образуют независимые пути выполнения функции.','На схеме фиксируют и общие элементы: ИБП, коммутатор, стойку. При аварии сначала определяют масштаб и разрешённые действия. Обслуживание электрической части выполняет допущенный персонал; оператор ИС проверяет доступные индикаторы и передаёт наблюдения.'),
 E('Один симптом — разные границы отказа','Учебные наблюдения: у одного АРМ нет питания, остальные принимают документы; затем недоступны все АРМ, но серверная консоль работает. В первом случае проверка начинается на рабочем месте; во втором — на общем пути доступа.','Число затронутых пользователей помогает выбрать область проверки, но не доказывает причину. Во втором случае общий путь может включать сеть, авторизацию и сервис. Поэтому после проверки физической связи продолжают проверять приложение.')],Check('Два сервера питаются через один ИБП. Что нужно показать на схеме?', ['Два полностью независимых канала','Общий ИБП как зависимость обоих серверов','Только имена приложений','Один сервер можно не учитывать'],1,'Общий физический компонент может нарушить работу обоих серверов. Дублирование корпусов не устраняет эту зависимость.'),'Техническую схему проверяют по ролям оборудования и общим зависимостям.'),
Q('software','Программное обеспечение','На исправном оборудовании функция может не выполняться из-за правил приложения, драйвера или базы. Разложим программный путь операции по ролям.',[
 S('Системные и прикладные программы','Операционная система управляет ресурсами и доступом к устройствам. Драйвер связывает ОС с оборудованием. СУБД хранит и изменяет структурированные данные, а прикладной сервис реализует правила приёмки, выдачи или поиска.','СУБД не знает сама по себе, разрешён ли отпуск товара без подтверждения. Это правило задают приложение и конфигурация. И наоборот, исправная бизнес-логика не компенсирует недоступный драйвер сканера. При диагностике фиксируют слой, на котором наблюдалась ошибка.'),
 S('Клиент, сервис и база данных','Клиент передаёт запрос сервису; сервис проверяет права и условия, обращается к базе и возвращает результат. Сообщение клиента и сохранённая запись — разные наблюдения: ответ может потеряться уже после успешной записи.','Если после тайм-аута оператор повторяет проведение, сервис должен распознать уже обработанный документ. Учебная проверка использует тот же номер П-17. Новый номер обозначал бы новую операцию и не проверял защиту от повтора.',visual=process([('Клиент','Запрос П-17'),('Сервис','Правила и идентификатор'),('База','Одна запись движения'),('Клиент','Подтверждение результата')],'Стрелки показывают логические этапы обработки; подтверждение должно соответствовать сохранённой операции.')),
 E('Совместимость программ проверяется комплектом','Учебный стенд: клиент версии A работает с сервисом A; обновлён только клиент до B, после чего сервер отклоняет формат запроса. Сеть доступна, но операция не проходит.','Вывод относится к совместимости формата. Сверьте поддерживаемую пару версий и журнал запроса; не обновляйте сразу все компоненты без плана возврата. После согласования версий выполните контрольную операцию, а не только вход в приложение.')],Check('После обновления клиента сервер отклоняет формат запроса. Какие два свидетельства полезны?', ['Версии клиента и сервера','Содержимое сообщения об отклонении формата','Цвет корпуса сервера','Число клавиш на клавиатуре'],[0,1],'Пара версий и сообщение о формате позволяют проверить гипотезу несовместимости. Внешний вид оборудования не описывает протокол.'),'Программный путь включает ОС, драйверы, сервисы и СУБД с согласованными интерфейсами.'),
Q('information','Информационное обеспечение','Следующий вопрос — с какими сведениями работает система. Исправная программа может точно обработать неверные исходные данные.',[
 S('Справочники и документы','Справочник описывает устойчивые объекты: товары, единицы, склады, контрагентов. Документ фиксирует событие с датой, номером и количеством. Документ ссылается на идентификатор товара; одинаковое наименование ещё не означает один объект.','Две карточки «Кабель» могут различаться сечением и единицей учёта. Поэтому замена кода по похожему названию опасна. При исправлении справочника нужно проверить связанные документы и сохранить смысл уже выполненных операций.'),
 S('Структура, кодирование и правила проверки','Для каждого поля определяют смысл, тип, допустимые значения и связи. Код товара «004281» является идентификатором: ведущие нули сохраняют. Проверка формата выявляет недопустимые символы, а проверка по справочнику — существование объекта.','Преобразование кода в число даст 4281 и может разорвать поиск, хотя арифметическая величина совпадает. Сначала выясняют семантику поля. Дата поставки также требует смысловой проверки: корректная календарная дата может относиться к другому документу.'),
 E('Исправление данных меняет вывод','Учебные данные: остаток A — 12 упаковок по 10 штук; заявка — 100 штук. Доступно 120 штук, дефицита нет. Если 12 ошибочно трактовали как штуки, получили бы ложный дефицит 88.','Расчёт проверяется после приведения единиц. Исправлять число 12 на 120 в исходном поле упаковок нельзя: это создаст новый дефект. Сохраняют исходную величину и преобразование, а затем повторяют расчёт потребности.')],Check('Код 004281 при импорте стал 4281. Какое действие обосновано?', ['Всегда дописать два нуля ко всем значениям','Уточнить формат идентификатора и повторить импорт с сохранением кода','Считать коды равными без сверки'],1,'Код — идентификатор, а не количество. Правило исправления должно опираться на формат и эталон, а не на догадку о числе нулей.'),'Информационное обеспечение включает смысл, структуру, справочники и правила качества данных.'),
Q('responsibility','Организационное и правовое обеспечение','Люди и документы определяют, кто вправе выполнять действие и как действовать при исключении. Разделим порядок работы и основания использования ресурсов.',[
 S('Роли и разделение ответственности','Роль задаёт разрешённые действия; конкретного исполнителя назначают на роль. Для приёмки можно разделить ввод, подтверждение и исправление. Администратор технически способен менять настройки, но это не делает его подтверждающим каждую поставку.','У назначения есть основание, срок и порядок отмены. Отдельно описывают замещение отсутствующего сотрудника. Передача его личного пароля не заменяет назначение роли: журнал перестаёт показывать реального исполнителя.'),
 S('Регламент нормального и исключительного случая','Инструкция определяет входные документы, порядок действий, проверку результата и остановку при расхождении. Регламент инцидента задаёт, что фиксировать, кому передавать и кто принимает решение о восстановлении.','Фраза «при ошибке обратиться к администратору» недостаточна. Полезная запись содержит время, номер операции, точное сообщение, затронутые рабочие места и уже выполненные безопасные проверки. Пароли и лишние персональные данные в неё не включают.'),
 S('Основание использования программ и сведений','Правовое обеспечение включает применимые договоры, лицензии и основания доступа к сведениям. Разрешение войти в интерфейс, локальная инструкция и право использовать данные в новой цели — разные вопросы. Конкретные основания устанавливают по действующим документам организации.','Для учебной модели фиксируем документ и ответственного, а не придумываем универсальную лицензию. Например, условия доступа поставщика к данным проверяются отдельно от настройки его роли. Техническое разрешение сервера само по себе не подтверждает допустимость такого доступа.'),
 E('Матрица ролей обнаруживает пробел','Учебная матрица: оператор вводит П-17; старший смены подтверждает; администратор восстанавливает сервис. Старший отсутствует, замещение не назначено. Программа работает, но нет разрешённого пути завершения приёмки.','Восстановление функции требует согласованного назначения замещающего и контрольной операции. Не выдавайте всем роль администратора: она расширит полномочия, но не определит ответственность.',table(['Роль','Разрешённое действие','Проверка'],[['Оператор','Ввод П-17','Автор документа'],['Старший смены','Подтверждение','Исполнитель в журнале'],['Администратор','Восстановление сервиса','Журнал изменений']],'Замещение отсутствующего подтверждающего задаётся организационным порядком.'))],Check('Какие два действия сохраняют ответственность при отсутствии подтверждающего?', ['Передать его пароль','Назначить замещающего по принятому порядку','Сохранить реального исполнителя в журнале','Отключить журнал'],[1,2],'Роль и журнал должны отражать действующего исполнителя. Обход учёта уничтожает возможность проверить ответственность.'),'Роль, регламент и основание доступа рассматривают раздельно и согласуют между собой.'),
Q('boundary','Граница системы и интерфейсы','Вернёмся к внешнему поставщику. Его данные нужны нашей функции, но это не означает, что мы управляем его системой.',[
 O(3),
 S('Функциональная и физическая границы','Функциональная граница охватывает выбранную работу и необходимые компоненты. Физическая граница показывает размещение. Облачный сервис может участвовать во внутренней функции предприятия, оставаясь внешним по эксплуатации инфраструктуры.','Поэтому на схеме нужны подписи ответственности. Поставщик облака может обслуживать оборудование, а предприятие — пользователей и правила приложения. Формулировка «всё отвечает облако» не объясняет, кто исправит неверную номенклатуру.'),
 E('Контракт обмена с внешней системой','Учебный обмен: поставщик передаёт номер накладной, код товара, количество и единицу; склад отвечает «принято» или «отклонено с причиной». При потере ответа повтор той же накладной должен связываться с прежним результатом.','Контракт описывает не только поля, но и повтор, тайм-аут, ответственность за исправление и сверку. Если внешний код неизвестен, склад помещает сообщение в разбор, а не создаёт товар с догаданными свойствами.')],Check('Сервер размещён у провайдера. Кто отвечает за правильность введённого оператором количества?', ['Это определяется распределением ответственности; размещение само по себе ответа не даёт','Всегда производитель сервера','Всегда провайдер сети'],0,'Место размещения не назначает ответственность за бизнес-данные. Нужны согласованные роли и договорённости.'),'Граница фиксирует функцию, окружение, интерфейсы и распределение ответственности.'),
Q('operation','Проверка системы как целого','Соберём обеспечения в один маршрут. Окончание диагностики должно подтверждать исходную функцию, а не последнюю исправленную деталь.',[
 O(4),
 S('Сквозная проверка после изменения','После исправления выполняют разрешённую учебную операцию от ввода до результата. Фиксируют исходное состояние, идентификатор, исполнителя, итоговую запись и отсутствие нежелательного повтора. Проверка отдельного узла остаётся промежуточным свидетельством.','Для П-17 подтверждаем остаток 34, единственный документ и корректную роль. Затем повторяем запрос с тем же номером и убеждаемся, что остаток не стал 58. Такая проверка связывает программное правило с качеством данных и организационным порядком.'),
 E('Одна остановка, несколько последствий','Учебный случай: после ремонта питания терминал включился, но товар не найден из-за обрезанного кода 004281. Технический дефект устранён; информационный дефект продолжает блокировать функцию.','Не записывайте «система восстановлена» по включённому экрану. Уточните код, устраните преобразование и повторите приёмку. Этот пример не означает, что всякая авария имеет две причины; он показывает необходимость завершать проверку по функции.')],Check('Какое наблюдение завершает восстановление приёмки?', ['Терминал включился','Ping вернул ответ','Разрешённый сотрудник провёл учебный документ; запись и остаток проверены','Закрыто сообщение об ошибке'],2,'Именно сквозная операция проверяет требуемый результат всех участвующих обеспечений.'),'После изменения проверяют всю функцию и документируют фактический результат.')
], [('Почему работающий сервер не доказывает работоспособность складской ИС?','Функция зависит также от правил, данных, полномочий и фактического завершения операции.'),('Где проходит граница при обмене накладными с поставщиком?','Поставщик остаётся окружением; интерфейс, проверка и обработка повторов входят в описание нашей системы.'),('Как отличить информационную причину остановки от технической?','Сопоставить свидетельства: питание и связь относятся к узлу; код, единица и справочник — к смыслу данных. Итог подтверждается сквозной операцией.')],H('Для учебной системы выдачи инструментов составьте границу: сотрудник запрашивает инструмент, кладовщик выдаёт его по карточке, внешний сервис сообщает срок поверки.','Используйте пять видов обеспечения и обозначьте, кто отвечает за каждый интерфейс. Не приписывайте внешнему сервису функции склада.','Представьте схему, таблицу пяти обеспечений и проверку одной выдачи.','Внутри выбранной функции — запрос, решение о допуске, выдача и запись; сервис поверки — внешняя зависимость. Нужны код инструмента, действующий статус, полномочие и подтверждение изменения состояния.'))

Lecture('structure',[
Q('workplace','Рабочее место и клиент','Разберём состав рабочего места по действиям пользователя. Оно может выглядеть исправным, хотя запрос не достигает сервиса.',[
 O(1),S('Толстый, тонкий и браузерный клиент','Локальный клиент может выполнять часть проверок и обработки; браузерный клиент получает интерфейс с сервера; терминальный доступ переносит выполнение приложения на удалённый узел. Во всех случаях остаются устройство ввода, экран, сеть и точка выполнения программы.','Тип клиента не определяет автоматически надёжность. Браузеру нужны совместимый интерфейс и соединение; локальной программе — согласованная версия. При описании указывают, где хранятся рабочие данные и что произойдёт при разрыве связи.'),E('Состояние формы и сохранённая запись','Учебное наблюдение: оператор ввёл 6 позиций, связь пропала до подтверждения. На экране позиции видны, но в базе документ отсутствует. Введённые значения ещё не равны зарегистрированному движению.','После восстановления проверяют документ по идентификатору. Если он существует, повторную операцию не создают; если нет — ввод восстанавливают по принятому порядку. Для неподтверждённого документа нельзя показывать новый остаток как окончательный.')],Check('Где искать доказательство сохранения документа?', ['Только в заполненной форме','В подтверждённой записи сервиса или хранилища по номеру документа','В яркости экрана'],1,'Форма может хранить несохранённое состояние; нужна запись, соответствующая операции.'),'Рабочее место обеспечивает ввод и показ, а сохранение проверяют отдельно.'),
Q('servers','Серверные роли','Слово «сервер» обозначает и устройство, и программную роль. Уточним, какой именно сервис обслуживает запрос.',[
 S('Физический сервер и виртуальная машина','Физический сервер предоставляет процессор, память, диски и сетевые интерфейсы. На нём могут работать несколько виртуальных машин. У каждой — своя ОС и службы, но общий отказ физического узла может затронуть их все.','Нарисуйте одну физическую машину и две виртуальные. Перезапуск одной гостевой ОС не равен отключению корпуса. При работах нужно знать, какие соседние сервисы используют общий узел и кто согласует остановку.'),
 S('Приложение, база и файловый сервис','Сервер приложения обрабатывает правила предметной области; сервер базы выполняет запросы к данным; файловый сервис предоставляет файлы. Роли можно разместить совместно, но их журналы и проверки различаются.','Отчёт может открываться с файлового ресурса, хотя база недоступна. Доступность одного сервиса не подтверждает другой. В паспорте роли связывают с адресом, портом, службой и владельцем данных.'),
 E('Один хост — несколько функций','Учебный узел SRV-01 содержит виртуальные APP-01 и DB-01. APP-01 отвечает на HTTP, но DB-01 остановлена: входная страница доступна, проведение документа завершается ошибкой.','Проверка сначала различает веб-интерфейс и обращение к базе. Запуск DB-01 требует принятого порядка; затем проверяют запись. Замена клиентского компьютера при одинаковом отказе у всех операторов не объясняет наблюдение.',table(['Объект','Что подтверждено','Чего это не доказывает'],[['SRV-01','Узел включён','Работу гостевых служб'],['APP-01','HTTP отвечает','Доступность базы'],['DB-01','Служба остановлена','Сохранение документа']],'Физический узел и программные роли — разные уровни проверки.'))],Check('Две виртуальные машины находятся на одном сервере. Какое утверждение верно?', ['Их физическое питание независимо','Они разделяют физический узел, хотя службы и ОС различаются','Остановка любой службы выключает корпус'],1,'Виртуализация разделяет программные окружения, но не устраняет общую физическую зависимость.'),'Серверную роль связывают с конкретным процессом и физическими зависимостями.'),
Q('data-path','Сеть и маршрут запроса','Проследим обращение от пользователя к записи. Физическое соединение и логика обработки образуют разные, связанные схемы.',[
 O(2),S('Канал, пакет и прикладной запрос','Кабель переносит сигнал; коммутатор передаёт кадры; IP помогает доставить пакеты между сетями; прикладной протокол задаёт смысл запроса. Проверка нижнего уровня не подтверждает все верхние уровни.','Наличие Link говорит о физическом соединении с соседним портом. Оно не доказывает правильный адрес сервера, открытый TCP-порт или разрешение провести документ. Диагностика поднимается к нужной функции, сохраняя результаты каждого уровня.'),E('Что меняет неправильное имя сервера','Учебные данные: APP-01 должен указывать на 192.168.10.20, но имя разрешается в .30. По адресу .20 контрольная страница открывается; по имени — другой ресурс.','Наблюдение выделяет разрешение имени как гипотезу. Сравните текущую запись с утверждённым адресом и повторите проверку после исправления. Доступ по адресу не разрешает навсегда заменить имена числами: это может нарушить настройки приложения.')],Check('Link горит, но имя APP-01 указывает на другой адрес. Что проверять дальше?', ['Только заменить все кабели','Разрешение имени и утверждённый адрес APP-01','Сразу форматировать накопитель'],1,'Есть конкретное расхождение имени и адреса; его нужно проверить до несвязанных вмешательств.'),'Маршрут запроса проверяют по уровням от соединения до результата приложения.'),
Q('storage','Хранилище и сохранность','Теперь отделим доступ к данным от их размещения и восстановления. Диск, файловый ресурс и резервная копия решают разные задачи.',[
 S('Локальное, сетевое и выделенное хранение','Локальный накопитель доступен через ОС узла. Сетевое файловое хранилище предоставляет файлы по сети. Выделенная система хранения может предоставлять дисковые ресурсы серверам. В каждом случае нужно знать владельца записи и путь доступа.','Термины NAS и SAN не следует использовать как синонимы любого сетевого диска. Для эксплуатационной схемы важнее показать, кто подключается, каким способом и что произойдёт при потере пути. Одна буква диска на АРМ не раскрывает физическое размещение.'),
 S('Массив дисков и резервная копия','Дисковый массив может позволить продолжить работу при отказе части накопителей. Резервная копия сохраняет отдельную восстановимую версию данных. Ошибочное удаление может быстро распространиться по массиву, поэтому массив не заменяет копию.','Копию оценивают по проверенному восстановлению и независимости от исходного отказа. Файл копии на том же отказавшем устройстве не обеспечивает нужный путь возврата. При проверке используют изолированное место, чтобы не заменить рабочую базу учебными данными.'),
 E('Расчёт места для учебного архива','За сутки создаётся 8 ГБ данных. Для 14 суток требуется 8×14=112 ГБ полезного места. Если задан запас 25% к расчёту, планируем 140 ГБ; место ОС, индексов и служебных данных учитывают отдельно.','Здесь запас считается от 112 ГБ, а не от ёмкости всего диска. Это оценка при постоянном объёме. При росте потока измерения повторяют; номинальная ёмкость накопителя и доступное полезное пространство не тождественны.')],Check('Какие два свидетельства относятся к проверке резервного копирования?', ['Есть сообщение «копия создана»','Копия восстановлена в изолированное место','Проверены дата копии и нужные записи','Два диска установлены в один корпус'],[1,2],'Нужны восстановимость и подходящая версия данных. Сообщение о создании и число дисков сами этого не подтверждают.'),'Надёжность хранения, версия копии и проверка восстановления — разные задачи.'),
Q('peripherals','Периферийное оборудование','Периферия связывает цифровые данные с физическим действием. Для неё проверяют и интерфейс, и содержание результата.',[
 S('Сканер, принтер и терминал сбора данных','Сканер преобразует код в последовательность символов; принтер формирует физическую метку; терминал может совмещать ввод, обработку и сеть. Подключение по USB или сети описывает канал, но не гарантирует правильную интерпретацию кода.','Проверьте ведущие нули, завершающий символ и единицу товара. Для принтера сравните напечатанный код с записью, а затем считайте его обратно. Видимая этикетка с неверным идентификатором создаёт ошибку следующих операций.'),
 O(4),E('Обратная проверка этикетки','Учебное задание: напечатать код 004281 для одной упаковки. Контроль включает читаемую надпись, считывание именно 004281 и выбор правильной карточки товара. Успешная печать пустого тестового листа этого не проверяет.','Сначала используйте один образец, чтобы не размножить ошибку на всю партию. Если символы совпали, а карточка другая, проверяйте справочник и сопоставление; если символы различаются — настройки ввода или самой метки.')],Check('После печати этикетки какой контроль подтверждает её назначение?', ['Лист вышел из принтера','Этикетка считалась как 004281 и открыла нужную карточку','Принтер издал звук'],1,'Проверка проходит весь путь от печати до предметного объекта.'),'Периферийный тест должен подтверждать смысл полученного кода или изображения.'),
Q('power','Питание и общие зависимости','Завершим структуру обеспечивающими компонентами. Их часто пропускают на схеме приложения, хотя они определяют масштаб аварии.',[
 O(3),S('ИБП и завершение работы','ИБП предоставляет ограниченное время питания и может поддерживать корректное завершение работы. Длительность зависит от фактической нагрузки, состояния батареи и режима. Наличие ИБП не означает бесконечную автономность.','Испытания проводят по утверждённому регламенту и документации оборудования. В учебной схеме обозначьте, какие узлы защищены. Если сервер на ИБП, а общий коммутатор нет, путь от АРМ всё равно может исчезнуть при отключении сети питания.'),E('Карта воздействия отказа','Учебный состав: два АРМ через SW-01 обращаются к APP-01 и DB-01; SW-01 питается отдельно без резерва. При отключении его питания оба АРМ теряют сервис, хотя серверы продолжают работать.','Покажите общий элемент и отделите недоступность от потери данных. После восстановления коммутатора подтвердите доступ и запись; не делайте вывод об исправности базы только по вернувшемуся Link.')],Check('Сервер на ИБП, общий коммутатор без него. Что можно утверждать?', ['Весь сервис гарантированно доступен при отключении питания','Питание сервера защищено, но общий путь доступа остаётся зависимым','Резервная копия больше не нужна'],1,'Защищён один компонент; условие успеха всей функции включает также сеть и клиентов.'),'Схема структуры должна показывать питание и общие точки отказа.')
],[('Чем серверная роль отличается от физического сервера?','Роль — выполняемая службой функция; один физический узел может поддерживать несколько ролей и быть их общей зависимостью.'),('Почему массив дисков не заменяет резервную копию?','Массив поддерживает доступность при некоторых аппаратных отказах, но не обязательно возвращает прежнюю версию после удаления или искажения.'),('Как проверить сканирование без подмены цели тестом соединения?','Считать известный код, сравнить точные символы и убедиться, что приложение выбрало правильный объект.')],H('Составьте структуру учебного пункта выдачи: 3 АРМ, сканер, сетевой принтер, коммутатор, APP-01 и DB-01 на одном физическом сервере, отдельное хранилище копий.','Покажите путь выдачи и два общих компонента. Для каждого элемента назовите проверяемую функцию.','Сдайте схему, перечень ролей и одну сквозную проверку выдачи.','Общие зависимости включают физический сервер и коммутатор. Сканер проверяют кодом, базу — записью, принтер — правильной меткой; копию проверяют восстановлением отдельно.'))

Lecture('classification',[
Q('purpose','Классификация по назначению','Сначала установим, какую работу поддерживает система. Одно решение может объединять несколько назначений, поэтому перечисление признаков должно сопровождаться примером функции.',[
 O(1),S('Учёт, управление и анализ','Учётная функция регистрирует факты и состояния; управляющая помогает выбрать и выполнить действие; аналитическая обобщает данные для решения. Отчёт о прошлых продажах и команда на выпуск партии используют данные, но дают разные результаты.','Сравните три объекта: проведённая накладная, производственное задание и прогноз потребности. Первое подтверждает факт, второе организует будущую работу, третье является оценкой с допущениями. Не превращайте прогноз в подтверждённый остаток.'),E('Многофункциональная система','Учебная ERP регистрирует приход, формирует заказ поставщику и строит отчёт об оборачиваемости. Назвать её только «аналитической» по наличию отчёта значит потерять две другие функции.','Классификация описывает выбранный ракурс. Для анализа эксплуатации дополнительно перечисляют критичные операции: остановка отчётности и остановка приёмки имеют разные последствия.',table(['Функция','Результат','Назначение'],[['Регистрация прихода','Документ и остаток','Учёт'],['Заказ поставщику','Согласованное действие','Управление снабжением'],['Анализ оборота','Сводный показатель','Аналитика']],'Одна система может иметь несколько функциональных назначений.'))],Check('Как классифицировать систему, которая ведёт учёт и строит аналитические отчёты?', ['Выбрать только одно назначение навсегда','Назвать оба назначения и соответствующие функции','Считать её облачной по наличию отчётов'],1,'Назначения могут сочетаться; способ размещения определяется отдельно.'),'Назначение определяют по функции и её результату; функции могут сочетаться.'),
Q('scale','Классификация по масштабу','Масштаб описывает охват работы и участников. Число компьютеров полезно, но не заменяет описание подразделений и общих данных.',[
 S('Индивидуальная, групповая и корпоративная ИС','Индивидуальная система поддерживает работу одного пользователя; групповая — совместную работу коллектива; корпоративная связывает процессы предприятия. Это учебные категории без универсального порога числа пользователей.','Программа на одном сервере может обслуживать всё предприятие, а сотни разрозненных таблиц не образуют общую корпоративную систему. Важны общие справочники, роли и процессы. Формулируйте масштаб через фактический охват.'),S('Территориальная распределённость','Несколько филиалов требуют описать связи между площадками, согласование общих данных и режим при недоступности канала. Распределённость по местам не означает автоматически независимость данных.','Если все филиалы пишут в центральную базу, потеря канала может остановить их операции. Если есть автономные узлы, возникают правила синхронизации и конфликтов. Это разные эксплуатационные модели при одинаковом количестве филиалов.'),O(2)],Check('Два филиала используют единый справочник и общий процесс закупки. Что описывает масштаб?', ['Только марка сервера','Охват филиалов, участников и общего процесса','Только тип интернет-браузера'],1,'Масштаб связан с организационным охватом, а не с маркой оборудования.'),'Масштаб фиксируют через участников, подразделения, процессы и общие данные.'),
Q('placement','Локальное, облачное и гибридное размещение','Теперь определим, где выполняются программы и хранятся данные. Этот признак независим от назначения и охвата.',[
 O(3),S('Ответственность при разных размещениях','При локальном размещении предприятие может обслуживать оборудование и приложение самостоятельно. В облаке часть ролей передана поставщику; границу задаёт выбранная услуга и договорённость. Гибридная схема соединяет локальные и внешние компоненты.','Внешнее размещение не снимает задачу управления пользователями и качеством введённых данных. Уточняйте, кто обновляет ОС, приложение и справочники, кто делает копии и кто подтверждает восстановление. Общая фраза «сервис в облаке» недостаточна.'),E('Автономность зависит от пути операции','Учебный склад хранит интерфейс на терминале, но каждый отпуск подтверждает в облачном сервисе. Без внешнего канала форма открывается, а подтверждение недоступно. Локальный интерфейс не даёт автономной работы.','Чтобы заявить автономность, нужно показать, какие операции выполняются без канала, где сохраняются записи и как они позднее согласуются. Наличие кэша справочника не доказывает возможность безопасной выдачи по общему остатку.')],Check('Интерфейс установлен локально, подтверждение выполняется в облаке. Что нужно проверить для автономности?', ['Только наличие ярлыка программы','Выполнение операции и согласование данных без внешнего канала','Только свободное место на рабочем столе'],1,'Автономность относится к полной функции, включая запись и последующую синхронизацию.'),'Размещение описывает места выполнения и хранения, а автономность проверяют сквозной операцией.'),
Q('comparison','Критерии сравнения одного назначения','Чтобы сравнение было полезным, кандидаты должны решать одну задачу и оцениваться по одинаковым исходным условиям.',[
 S('Обязательные требования и предпочтения','Обязательное требование отсекает неподходящий вариант. Предпочтение помогает сравнить оставшиеся варианты. Низкая цена не компенсирует нарушение обязательной автономности, если это условие задано до сравнения.','Сначала зафиксируйте задачу, пользователей и ограничения, затем соберите свидетельства по каждому кандидату. Не меняйте критерии после знакомства с понравившимся решением. Если сведения неизвестны, ставьте «не подтверждено», а не предполагаемое соответствие.'),S('Сравнимая стоимость и состав работ','Для учебного сравнения стоимость считают за один период и одинаковый состав: лицензии или подписка, внедрение, миграция, инфраструктура, сопровождение. Бесплатная загрузка клиента не означает нулевые затраты эксплуатации.','Если в одном расчёте есть перенос данных, а в другом его нет, итоговые суммы несопоставимы. Вместе с ценой сохраняют допущения: число пользователей, срок и необходимое оборудование. Изменение любого из них требует пересчёта.'),E('Расчёт на общем горизонте','Учебные цены за 2 года: A — внедрение 40 и сопровождение 10 в год; B — внедрение 10 и подписка 30 в год. Без других расходов A: 40+2×10=60; B: 10+2×30=70 условных единиц.','При горизонте один год A и B стоят 50 и 40, поэтому выбор по цене меняется. Это не универсальная рекомендация продукта: пример показывает влияние периода и одинакового состава затрат.')],Check('A стоит 40+10 в год, B — 10+30 в год. При заданных расходах сколько стоит A за 2 года?', ['50','60','70','80','100'],1,'Внедрение оплачивается один раз: 40+2×10=60. Для B за тот же период получается 70.'),'Сравнение требует общих критериев, горизонта и состава затрат.'),
Q('selection','Выбор и проверка вывода','Применим признаки к конкретным ограничениям. Обоснование должно объяснять не только победивший вариант, но и причину исключения остальных.',[
 O(4),S('Матрица решения и неопределённость','В таблице решения указывают требование, свидетельство, результат проверки и влияние на выбор. «Нет сведений» отличается от «не соответствует». Для критичного требования непроверенное соответствие не считают подтверждённым.','Например, поставщик обещает автономность, но демонстрация отключения канала не выполнена. Запишите пробел и способ проверки. Красивый интерфейс не является свидетельством автономного проведения документа.'),E('Изменение условия требует нового решения','Учебный выбор: B дороже, но только он подтверждённо работает без канала; автономность обязательна — остаётся B. После обеспечения надёжного внешнего канала автономность исключили из обязательных требований: теперь сравнивают оба варианта заново.','Нельзя объявить прежний выбор ошибочным без учёта изменившихся условий. Сохраняйте исходную матрицу и новую редакцию требований. Вывод относится к конкретной задаче, а не к абсолютному превосходству системы.')],Check('Поставщик не подтвердил обязательное свойство. Как записать результат?', ['Соответствует, раз обещал','Не подтверждено; указать нужное испытание','Не соответствует навсегда без проверки'],1,'Отсутствие доказательства нужно обозначить отдельно; для выбора нельзя выдавать его за подтверждённое соответствие.'),'Решение связывают с подтверждёнными требованиями и пересматривают при изменении условий.')
],[('Почему «облачная» и «учётная» не являются взаимоисключающими классами?','Они описывают разные основания: размещение и назначение.'),('Когда более дорогой вариант обоснованно остаётся единственным?','Когда остальные не выполняют подтверждённое обязательное требование.'),('Что должно измениться в выводе при смене горизонта стоимости?','Нужно пересчитать одинаковый состав затрат за новый период и повторить сравнение допущений.')],H('Сравните два условных решения для библиотеки на 3 года. A: внедрение 20, обслуживание 12 в год; B: внедрение 5, подписка 18 в год. Оба подтверждённо поддерживают выдачу и нужное число пользователей.','Назовите назначение, масштаб по заданному охвату и недостающие сведения о размещении. Посчитайте стоимость при отсутствии других расходов.','Сдайте таблицу признаков, расчёт и вывод с оговоркой о непроверенных свойствах.','Стоимость A=56, B=59 условных единиц; по заданным расходам A дешевле на 3. Размещение из цены не определяется; его нельзя выдумать.'))
